const games = new Map();

function formatHistory(attempts) {
    if (!attempts.length) return 'Brak prób';
    return attempts.map(a => {
        const blocks = a.colors.map(c => {
            if (c === 'green') return '🟩';
            if (c === 'yellow') return '🟨';
            return '⬛';
        }).join('');
        return `${blocks}  **${a.word.toUpperCase()}**`;
    }).join('\n');
}

function analyze(guess, target) {
    const colors = new Array(5).fill(null);
    const used = new Array(5).fill(false);

    for (let i = 0; i < 5; i++) {
        if (guess[i] === target[i]) {
            colors[i] = 'green';
            used[i] = true;
        }
    }

    for (let i = 0; i < 5; i++) {
        if (colors[i] === 'green') continue;

        for (let j = 0; j < 5; j++) {
            if (!used[j] && target[j] === guess[i]) {
                colors[i] = 'yellow';
                used[j] = true;
                break;
            }
        }
        if (colors[i] === null) colors[i] = 'gray';
    }

    return colors;
}

function buildStatusEmbed(game, resultMsg = '') {
    const attempts = game.attempts;
    const history = formatHistory(attempts);

    let hint = 'Brak wskazówki (jeszcze 2 próby)';
    if (attempts.length >= 2) {
        hint = `(💡) Wskazówka: Pierwsza litera to **${game.target[0].toUpperCase()}**`;
    }

    return new EmbedBuilder()
        .setTitle('🎯 Wordle - Ulepszona Edycja')
        .setDescription(
            `Masz **5 prób**, żeby odgadnąć słowo złożone z **5 liter**.\n\n` +
            `Wpisz próbę przez: \`/wordle słowo:XYZ\`\n\n` +
            `${resultMsg}\n` +
            `**Historia prób:**\n${history}`
        )
        .addFields(
            { name: '📊 Próby', value: `${attempts.length} / 5`, inline: true },
            { name: '🎯 Słowo ma', value: '5 liter', inline: true },
            { name: '💡 Wskazówka', value: hint, inline: false }
        )
        .setColor(attempts.length >= 4 ? '#e74c3c' : attempts.length >= 2 ? '#f1c40f' : '#3498db')
        .setFooter({ text: 'Wpisz /wordle słowo:KWIAT aby zagrać ponownie w tej sesji' });
}

module.exports = {
    data: new SlashCommandBuilder()
        .setName('wordle')
        .setDescription('Ulepszona gra Wordle! 5 prób, wskazówki, punkty, kolorowe bloki.')
        .addStringOption(opt =>
            opt.setName('slowo')
                .setDescription('Wpisz 5-literowe słowo (np. KWIAT)')
                .setRequired(false)
        ),

    async execute(interaction) {
        const user = interaction.user;
        const guessRaw = interaction.options.getString('slowo');
        const guess = guessRaw ? guessRaw.trim().toLowerCase() : null;
        const game = games.get(user.id);

        if (guess) {
            if (!game) {
                return interaction.reply({
                    content: '❌ Nie masz aktywnej gry. Wpisz `/wordle` (bez słowa), aby rozpocząć.',
                    ephemeral: true
                });
            }

            if (guess.length !== 5) {
                return interaction.reply({ content: '❌ Słowo musi mieć **dokładnie 5 liter**.', ephemeral: true });
            }
            if (!/^[a-ząćęłńóśźż]+$/i.test(guess)) {
                return interaction.reply({ content: '❌ Dozwolone tylko litery (bez cyfr i znaków).', ephemeral: true });
            }
            if (!WORD_LIST.includes(guess)) {
                return interaction.reply({ content: `❌ Słowo **${guess.toUpperCase()}** nie istnieje w słowniku!`, ephemeral: true });
            }

            const colors = analyze(guess, game.target);
            game.attempts.push({ word: guess, colors });

            const won = colors.every(c => c === 'green');
            const lost = game.attempts.length >= 5;

            if (won) {
                games.delete(user.id);
                const points = (6 - game.attempts.length) * 30 + (game.attempts.length === 1 ? 50 : 0);
                const embed = new EmbedBuilder()
                    .setTitle('🎉 WYGRAŁEŚ! - Wordle Pro')
                    .setDescription(
                        `Hasło **${game.target.toUpperCase()}** zostało odnalezione w **${game.attempts.length}** próbach!\n\n` +
                        `**Historia:**\n${formatHistory(game.attempts)}`
                    )
                    .addFields(
                        { name: '🏆 Punkty', value: `${points}`, inline: true },
                        { name: '💎 Bonus za 1. próbę', value: (game.attempts.length === 1 ? '+50' : 'Brak'), inline: true }
                    )
                    .setColor('#2ecc71');
                return interaction.reply({ embeds: [embed] });
            }

            if (lost) {
                games.delete(user.id);
                const embed = new EmbedBuilder()
                    .setTitle('💀 Koniec prób - Wordle Pro')
                    .setDescription(
                        `Hasło było: **${game.target.toUpperCase()}**\n\n` +
                        `**Historia:**\n${formatHistory(game.attempts)}`
                    )
                    .addFields(
                        { name: '(💡) Wskazówka', value: `Pierwsza litera: **${game.target[0].toUpperCase()}**`, inline: true },
                        { name: '(📊) Próby', value: `5 / 5`, inline: true }
                    )
                    .setColor('#e74c3c');
                return interaction.reply({ embeds: [embed] });
            }

            const embed = buildStatusEmbed(game, `✅ Wpisano **${guess.toUpperCase()}** - analizuję...`);
            return interaction.reply({ embeds: [embed] });
        }

        if (game) {
            const embed = buildStatusEmbed(game);
            return interaction.reply({ embeds: [embed] });
        }

        const target = WORD_LIST[Math.floor(Math.random() * WORD_LIST.length)];
        const newGame = {
            target,
            attempts: [],
            startTime: Date.now()
        };
        games.set(user.id, newGame);

        const embed = new EmbedBuilder()
            .setTitle('🎯 Wordle - Ulepszona Edycja')
            .setDescription(
                `Witaj, <@${user.id}>! Odgadnij **5-literowe** słowo.\n\n` +
                `Masz dokładnie **5 prób**. Wpisuj przez:\n\`/wordle słowo:KWIAT\`\n\n` +
                `**Legenda bloków:**\n` +
                `🟩 Litera na **właściwym** miejscu\n` +
                `🟨 Litera jest w słowie, ale **zła pozycja**\n` +
                `⬛ Litery **nie ma** w słowie`
            )
            .addFields(
                { name: '📊 Próby', value: '0 / 5', inline: true },
                { name: '🏆 Bonus', value: '+50 pkt za 1. próbę', inline: true },
                { name: '💡 Wskazówka', value: 'Pokazuje się po 2. błędnej próbie', inline: true }
            )
            .setColor('#3498db')
            .setFooter({ text: `Słowo wybrane losowo z ${WORD_LIST.length} pozycji.` });

        await interaction.reply({ embeds: [embed] });
    }
};